-- ═══════════════════════════════════════════════════════════
-- CATÁLOGO DE FILTROS GONHER — FerrePOS
-- Ejecutar en pgAdmin sobre la BD ferreteria
-- ═══════════════════════════════════════════════════════════

-- Tabla principal de compatibilidades
CREATE TABLE IF NOT EXISTS catalogo_filtros (
    id                  BIGSERIAL PRIMARY KEY,
    tipo                VARCHAR(50)  NOT NULL DEFAULT 'Automóvil', -- Automóvil, Camioneta, Moto, etc.
    marca               VARCHAR(100) NOT NULL,
    modelo              VARCHAR(200) NOT NULL,
    anio_inicio         INTEGER      NOT NULL,
    anio_fin            INTEGER      NOT NULL,
    motor               VARCHAR(100),
    filtro_aceite       VARCHAR(50),
    filtro_aceite_sin   VARCHAR(50),   -- versión sintética
    filtro_aire         VARCHAR(100),  -- puede tener varias claves
    filtro_combustible  VARCHAR(100),
    filtro_cabina       VARCHAR(100),  -- puede tener varias claves (GAC/GAF)
    notas               TEXT           -- ej: "NR = No Recomendado"
);

-- Índices para búsqueda rápida en cascada
CREATE INDEX IF NOT EXISTS idx_cf_tipo   ON catalogo_filtros(tipo);
CREATE INDEX IF NOT EXISTS idx_cf_marca  ON catalogo_filtros(marca);
CREATE INDEX IF NOT EXISTS idx_cf_modelo ON catalogo_filtros(modelo);
CREATE INDEX IF NOT EXISTS idx_cf_anio   ON catalogo_filtros(anio_inicio, anio_fin);
CREATE INDEX IF NOT EXISTS idx_cf_motor  ON catalogo_filtros(motor);

-- Índice de texto completo para búsqueda dinámica
CREATE INDEX IF NOT EXISTS idx_cf_fulltext ON catalogo_filtros
    USING gin(to_tsvector('spanish', marca || ' ' || modelo || ' ' || COALESCE(motor,'')));

-- Tabla de equivalencias (parte competidor → parte Gonher)
CREATE TABLE IF NOT EXISTS catalogo_equivalencias (
    id                  BIGSERIAL PRIMARY KEY,
    parte_competidor    VARCHAR(100) NOT NULL,
    marca_competidor    VARCHAR(100),
    parte_gonher        VARCHAR(50)  NOT NULL,
    tipo_filtro         VARCHAR(50)  -- ACEITE, AIRE, COMBUSTIBLE, CABINA
);

CREATE INDEX IF NOT EXISTS idx_equiv_parte ON catalogo_equivalencias(parte_competidor);









